mapper.select:
SELECT
e.id,
e.employee_no,
e.name,
e.email,
e.phone,
d.name as department_name,
e.position,
e.level,
e.base_salary,
e.hire_date,
e.status,
e.skills,
CONCAT(e.address_province, e.address_city, e.address_district, e.address_detail) as full_address,
e.created_time
FROM t_employee e
LEFT JOIN t_department d ON e.department_id = d.id


        AND e.name LIKE CONCAT('%', #{name}, '%')


        AND e.email = #{email}


        AND e.department_id IN

            #{deptId}



        AND e.position IN

            #{position}



        AND e.level IN

            #{level}



        AND e.status IN

            #{status}




            AND e.hire_date >= #{hireDateRange.startDate}


            AND e.hire_date <= #{hireDateRange.endDate}




            AND e.base_salary >= #{salaryRange.minSalary}


            AND e.base_salary <= #{salaryRange.maxSalary}



        AND e.address_province = #{province}


        AND e.address_city = #{city}


ORDER BY e.created_time DESC

SELECT id, employee_no, name, email, phone, department_id, position, level, status, hire_date FROM t_employee WHERE department_id IN
#{deptId}
ORDER BY department_id, name
